-- =============================================================================
-- HFM · IBGE reference data: states and cities
--
-- Platform reference data, not tenant data: there is one Brazil, and every
-- organization reads the same rows. So no organization_id, no per-tenant copy,
-- and RLS that grants read to any signed-in user while writes stay with the
-- service role. Nothing here is ever edited by a customer.
--
-- The primary key IS the IBGE code. A surrogate uuid would let two rows claim
-- the same municipality, and the whole point of this table is to be the single
-- answer to "which city is this".
--
-- The rows below are IBGE's own list and are embedded so that `supabase db push`
-- reproduces the table in full. The linked project received them through a
-- one-shot loader instead, and the result was checked against this same dataset
-- by SHA-256 over (código, nome, DDD, latitude, longitude) before that loader
-- was retired; the per-state counts were checked against IBGE's published
-- figures as well.
-- =============================================================================

create table public.states (
  id        smallint primary key,
  uf        char(2)  not null unique,
  name      text     not null,
  region    text     not null,
  latitude  numeric(9,6),
  longitude numeric(9,6),

  constraint states_uf_check     check (uf ~ '^[A-Z]{2}$'),
  constraint states_name_check   check (length(btrim(name)) between 2 and 60),
  constraint states_region_check check (region in ('Norte', 'Nordeste', 'Centro-Oeste', 'Sudeste', 'Sul')),
  constraint states_code_check   check (id between 11 and 53)
);

comment on table public.states is
  'Brazilian federative units, keyed by their IBGE code. Reference data shared by every organization.';

create table public.cities (
  id              integer  primary key,
  state_id        smallint not null references public.states (id) on delete restrict,
  name            text     not null,
  is_capital      boolean  not null default false,
  is_municipality boolean  not null default true,
  ddd             smallint,
  time_zone       text,
  latitude        numeric(9,6),
  longitude       numeric(9,6),

  constraint cities_name_check check (length(btrim(name)) between 1 and 120),
  constraint cities_code_check check (id between 1000000 and 5399999),
  -- The first two digits of a 7-digit IBGE municipality code are its UF code.
  -- Enforced rather than trusted: it makes a row that belongs to the wrong
  -- state impossible to write, which no amount of import care can guarantee.
  constraint cities_state_prefix_check check (id / 100000 = state_id),
  constraint cities_ddd_check check (ddd is null or ddd between 11 and 99)
);

comment on table public.cities is
  'Brazilian municipalities, keyed by their 7-digit IBGE code. is_municipality is false for Fernando de Noronha, which carries a code but is a state district of Pernambuco rather than a municipality.';

create index cities_state_idx on public.cities (state_id);
create index cities_name_idx  on public.cities (private.normalize_label(name));
create index cities_name_trgm_idx on public.cities using gin (private.normalize_label(name) extensions.gin_trgm_ops);

-- ---------------------------------------------------------------------------
-- Access. Reference data: readable by anyone signed in, written by no one but
-- the service role. anon gets nothing, in line with every other table here.
-- ---------------------------------------------------------------------------
alter table public.states enable row level security;
alter table public.cities enable row level security;

create policy states_select on public.states for select to authenticated using (true);
create policy cities_select on public.cities for select to authenticated using (true);

revoke all on public.states from anon, authenticated;
revoke all on public.cities from anon, authenticated;
grant select on public.states to authenticated;
grant select on public.cities to authenticated;
grant select, insert, update, delete on public.states to service_role;
grant select, insert, update, delete on public.cities to service_role;

